type Hook<F> = F extends (...args: infer A) => Promise<infer R>
  ? (args: A, result: R) => void
  : never;

/**
 * Observers of the calls the UI makes through `window.go` (bridge.installWailsGlobals): called with
 * the arguments and the result once a binding answered.
 */
export type BindingHooks = {
  -readonly [S in keyof CoreClient]?: { -readonly [M in keyof CoreClient[S]]?: Hook<CoreClient[S][M]> };
};
